use super::*;
use semio_s_plugin_energy_engine_calendar::SimDate;
#[test]
fn authored_weather_chronology_matches_neutral_midnight_leap_rollover_and_refusal_oracles(){
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../📅️chronology/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["runPeriods"].as_array().unwrap(){let period:semio_s_plugin_energy_engine_calendar::RunPeriod=serde_json::from_value(row["period"].clone()).unwrap();assert_eq!(period.is_interval(),row["admitted"].as_bool().unwrap());if period.is_interval(){let hours=period.hours().collect::<Vec<_>>();assert_eq!(hours.len(),row["hours"].as_u64().unwrap()as usize);assert_eq!(period.total_hours(),hours.len()as u32);let(date,hour,_)=hours.last().unwrap();assert_eq!([date.year as u64,date.month as u64,date.day as u64],[row["end"][0].as_u64().unwrap(),row["end"][1].as_u64().unwrap(),row["end"][2].as_u64().unwrap()]);assert_eq!(*hour,23);}}
 for case in fixture["cases"].as_array().unwrap(){let policy:WeatherCalendar=serde_json::from_value(case["calendar"].clone()).unwrap();let records:Vec<WeatherRecord>=serde_json::from_value(case["records"].clone()).unwrap();let admitted=records.iter().enumerate().all(|(i,r)|admit_row(policy,records[0],i.checked_sub(1).map(|i|records[i]),*r));assert_eq!(admitted,case["admitted"].as_bool().unwrap(),"{}",case["id"]);if !admitted{continue;}
 for query in case["queries"].as_array().unwrap(){let date=&query["date"];let index=record_index(policy,records.len(),|i|records.get(i).copied(),SimDate::new(date[0].as_u64().unwrap()as u16,date[1].as_u64().unwrap()as u8,date[2].as_u64().unwrap()as u8),query["hour"].as_u64().unwrap()as u8);if query["expected"].is_null(){assert!(index.is_none(),"{}",case["id"]);continue;}let index=index.expect("authored hour must be selected");let neighbourhood=neighbours(records.len(),|i|records.get(i).copied(),index,if query["policy"]=="RepeatDay"{NeighbourPolicy::RepeatDay}else{NeighbourPolicy::Continuous}).unwrap();for(i,row)in neighbourhood.iter().enumerate(){assert_eq!(*row,records[query["expected"][i].as_u64().unwrap()as usize],"{}",case["id"]);}let interpolation=super::super::TimestepWeather::interpolate(&neighbourhood[0],&neighbourhood[1],&neighbourhood[2],2,2);assert_eq!(interpolation.beam_normal_w_m2,(neighbourhood[1].direct_normal_irradiance_w_m2+neighbourhood[2].direct_normal_irradiance_w_m2)*0.5);}
 }
 eprintln!("[DEBUG] Energy actual weather chronology10 neutral admission/midnight/leap/year-rollover/warmup cases passed");
}
